"""Step `report`: statistics of the ontology and of the example export.

Writes docs/report.md (also printed in short).  Everything is computed from
ontology/qskos.ttl and ontology/example.ttl, no clock, so a rerun is identical.
"""
from __future__ import annotations

from collections import Counter

from . import ontology_io as oio
from rdflib import Graph
from rdflib.namespace import OWL, RDF, RDFS

HEADER = ("<!-- Generated by tools/main.py (step: report). "
          "Do not edit by hand; edit the generator or the inputs. -->\n\n")


def compute():
    onto = oio.ontology()
    ex = Graph().parse(oio.EXAMPLE)
    classes = oio.qskos_classes(onto)
    props = oio.qskos_properties(onto)
    subs = sum(len(oio.direct_superclasses(onto, c)) for c in classes)
    typ = Counter(oio.short(o) for _, o in ex.subject_objects(RDF.type))
    pred = Counter(oio.short(p) for _, p, _ in ex)
    return {
        "onto_triples": len(onto), "n_classes": len(classes), "n_props": len(props),
        "n_subclass": subs, "ex_triples": len(ex), "types": typ, "preds": pred,
        "subjects": len(set(ex.subjects())),
    }


def render(st) -> str:
    L = [HEADER, "---\ntitle: Report\n---\n\n# Report: ontology and example export\n\n",
         "Computed from `ontology/qskos.ttl` and `ontology/example.ttl` (a synthetic export: "
         "one object, one layer, three features, three annotations).\n\n",
         "## Ontology\n\n| | |\n|---|---|\n",
         f"| Triples | {st['onto_triples']} |\n| QSKOS classes | {st['n_classes']} |\n"
         f"| QSKOS properties | {st['n_props']} |\n| `rdfs:subClassOf` links to foreign classes | {st['n_subclass']} |\n\n",
         "## Example export\n\n| | |\n|---|---|\n",
         f"| Triples | {st['ex_triples']} |\n| Distinct subjects | {st['subjects']} |\n\n",
         "### Instances per class\n\n| Class | Instances |\n|---|---|\n"]
    for k, v in sorted(st["types"].items()):
        L.append(f"| `{k}` | {v} |\n")
    L.append("\n### Triples per predicate\n\n| Predicate | Triples |\n|---|---|\n")
    for k, v in sorted(st["preds"].items()):
        L.append(f"| `{k}` | {v} |\n")
    L.append("\nThe example uses `qskos:` classes only (plus `sf:` geometry types, the chosen "
             "E18 subclass on the object and `skos:ConceptScheme` on the vocabulary scheme); "
             "the crosswalk classes appear in no instance triple.\n")
    return "".join(L)


def run(**_):
    st = compute()
    oio.DOCS.mkdir(exist_ok=True)
    (oio.DOCS / "report.md").write_text(render(st), encoding="utf-8", newline="\n")
    print(f"  ontology: {st['n_classes']} classes, {st['n_props']} properties, {st['onto_triples']} triples")
    print(f"  example : {st['ex_triples']} triples, {st['subjects']} subjects  -> docs/report.md")
